def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row), key=lambda c: sum(row.count(c) for row in grid))
    out = [row[:] for row in grid]
    # In these tasks, a small colored shape is recolored to the color of the
    # larger, line-like shape which it matches in orientation.
    # Detect the unusual isolated compact component and use the dominant
    # non-background color among elongated components as its replacement.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            col = grid[r][c]
            if col == bg or (r,c) in seen:
                continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==col:
                        seen.add((yy,xx)); stack.append((yy,xx))
            comps.append((col,cells))
    # Find the most common color of long, thin components as the indicator.
    elongated=[]
    for col,cells in comps:
        ys=[p[0] for p in cells]; xs=[p[1] for p in cells]
        hh=max(ys)-min(ys)+1; ww=max(xs)-min(xs)+1
        if len(cells)>=2 and (hh==1 or ww==1):
            elongated.append((len(cells),col))
    if not elongated:
        return out
    target_color=max(elongated)[1]
    # Recolor compact small components that are not themselves line components.
    candidates=[]
    for col,cells in comps:
        ys=[p[0] for p in cells]; xs=[p[1] for p in cells]
        hh=max(ys)-min(ys)+1; ww=max(xs)-min(xs)+1
        if len(cells)>=2 and hh>1 and ww>1:
            candidates.append((len(cells),col,cells))
    if candidates:
        _,_,cells=max(candidates)
        for r,c in cells:
            out[r][c]=target_color
    return out
